#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The console-only steps of pushes (issue #63): the APNs auth key from the Apple Developer portal, stored in AWS
# Secrets Manager as birdjournal/apns for the API to sign its provider tokens with; Push Notifications on the App ID;
# the deploy; and a test push to a phone.
#
#   infra/scripts/push-wizard.sh                  # from the start
#   WIZARD_FROM=3 infra/scripts/push-wizard.sh    # resume at stage 3 (e.g. after the key is stored)
#
# Run infra/scripts/accounts-wizard.sh first (and circles-wizard.sh: every deploy needs its certificate). The key
# never goes into the stack, the repo or ~/keys/birdjournal.env: only its Key ID and Team ID are saved there, and
# the .p8 itself goes straight into Secrets Manager. Apple lets you download it once; keep the file safe or revoke
# it and make another.

run_wizard() {

TOTAL_STAGES=5
WIZARD_FROM="${WIZARD_FROM:-1}"

for tool in aws jq uv; do
  command -v "$tool" >/dev/null 2>&1 || { printf '%s is required: brew install %s\n' "$tool" "$tool" >&2; exit 1; }
done

INFRA_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_DIR="$(cd "$INFRA_DIR/.." && pwd)"
mkdir -p "$HOME/keys"
ENV_FILE="$HOME/keys/birdjournal.env"
AWS_REGION="us-west-2"
export AWS_PROFILE="${AWS_PROFILE:-lsvr-admin}"
SECRET_NAME=$(jq -r '.context.apnsSecretName' "$INFRA_DIR/cdk.json")
BUNDLE_ID=$(jq -r '.context.apnsTopic' "$INFRA_DIR/cdk.json")
TEAM_ID_DEFAULT="647FZYVR5Q"
TAGS=(Key=project,Value=birdjournal)

# Fail before the browser work, not after it.
AWS_ACCOUNT=$(aws sts get-caller-identity --query Account --output text 2>/dev/null) || {
  printf 'AWS profile %s has no working credentials (aws sso login --profile %s?). Fix that, then re-run.\n' \
    "$AWS_PROFILE" "$AWS_PROFILE" >&2
  exit 1
}

# begin "Name" starts the next stage, or skips it (returning 1) when it comes before WIZARD_FROM.
begin() {
  if (( _STAGE_INDEX + 1 < WIZARD_FROM )); then _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 1; fi
  stage "$1"
}

secret_exists() { aws secretsmanager describe-secret --region "$AWS_REGION" --secret-id "$SECRET_NAME" >/dev/null 2>&1; }

api_function() {
  aws cloudformation describe-stack-resources --region "$AWS_REGION" --stack-name BirdJournal \
    --query "StackResources[?ResourceType=='AWS::Lambda::Function' && starts_with(LogicalResourceId, 'ApiFunction')].PhysicalResourceId | [0]" \
    --output text 2>/dev/null || true
}

banner "BirdJournal: pushes (APNs key, App ID, deploy)"

if begin "Apple Developer: create the APNs auth key"; then
  say "The API signs every push with a token key: one .p8 works for all your apps, sandbox and production."
  note "Already have an APNs key for this team? Reuse it: enter its Key ID and .p8 path below."
  open_url "https://developer.apple.com/account/resources/authkeys/list"
  step "Keys → the + button. Key Name: BirdJournal APNs."
  step "Tick 'Apple Push Notifications service (APNs)' → Configure:"
  step "  Environment: Sandbox & Production · Key Restriction: Team Scoped (All Topics) → Save."
  step "Continue → Register → Download. Apple offers the .p8 once; move it to ~/keys (chmod 600)."
  step "Copy the Key ID shown on the page (10 characters)."
  printf '\n'
  until ask APNS_KEY_ID "Key ID:" && [[ "$APNS_KEY_ID" =~ ^[A-Z0-9]{10}$ ]]; do warn "A Key ID is 10 capital letters and digits."; done
  write_env APNS_KEY_ID "$APNS_KEY_ID"
  [[ -n "$(_existing APNS_TEAM_ID || true)" ]] || write_env APNS_TEAM_ID "$TEAM_ID_DEFAULT"
  note "Team ID: top right of the developer portal, under your name ($TEAM_ID_DEFAULT for Lightsail VR)."
  until ask APNS_TEAM_ID "Team ID:" && [[ "$APNS_TEAM_ID" =~ ^[A-Z0-9]{10}$ ]]; do warn "A Team ID is 10 capital letters and digits."; done
  write_env APNS_TEAM_ID "$APNS_TEAM_ID"
  pause
fi

if begin "AWS Secrets Manager: store the key as $SECRET_NAME"; then
  APNS_KEY_ID="${APNS_KEY_ID:-$(_existing APNS_KEY_ID || true)}"
  APNS_TEAM_ID="${APNS_TEAM_ID:-$(_existing APNS_TEAM_ID || true)}"
  [[ -n "$APNS_KEY_ID" && -n "$APNS_TEAM_ID" ]] || { warn "No Key ID or Team ID saved: run stage 1 first."; exit 1; }
  note "Account $AWS_ACCOUNT · profile $AWS_PROFILE · region $AWS_REGION"
  default_path="$HOME/keys/AuthKey_${APNS_KEY_ID}.p8"
  [[ -f "$default_path" ]] || default_path="$HOME/Downloads/AuthKey_${APNS_KEY_ID}.p8"
  key_path=""
  while :; do
    read -e -r -p "  ${BOLD}Path to the .p8${RESET} ${DIM}[$default_path]${RESET} " key_path || exit 1
    key_path="${key_path:-$default_path}"
    key_path="${key_path/#\~/$HOME}"
    if [[ -f "$key_path" ]] && grep -q "BEGIN PRIVATE KEY" "$key_path"; then
      # Apple names the download AuthKey_<Key ID>.p8: a different ID there means the saved Key ID belongs to another key
      # (Sign in with Apple's, say), and APNs would refuse every push with InvalidProviderToken.
      file_id=$(basename "$key_path" | sed -nE 's/^AuthKey_([A-Z0-9]{10})\.p8$/\1/p')
      if [[ -n "$file_id" && "$file_id" != "$APNS_KEY_ID" ]]; then
        warn "This file is key $file_id, but the saved Key ID is $APNS_KEY_ID."
        if confirm "Use $file_id as the Key ID?"; then
          APNS_KEY_ID="$file_id"
          write_env APNS_KEY_ID "$APNS_KEY_ID"
        else
          continue
        fi
      fi
      break
    fi
    warn "That isn't a .p8 key file ($key_path)."
  done
  jq -n --arg key_id "$APNS_KEY_ID" --arg team_id "$APNS_TEAM_ID" --rawfile private_key "$key_path" \
    '{key_id: $key_id, team_id: $team_id, private_key: $private_key}' > "${TMPDIR:-/tmp}/birdjournal-apns.$$"
  trap 'rm -f "${TMPDIR:-/tmp}/birdjournal-apns.$$"' EXIT
  chmod 600 "${TMPDIR:-/tmp}/birdjournal-apns.$$"
  if secret_exists; then
    aws secretsmanager put-secret-value --region "$AWS_REGION" --secret-id "$SECRET_NAME" \
      --secret-string "file://${TMPDIR:-/tmp}/birdjournal-apns.$$" >/dev/null
  else
    aws secretsmanager create-secret --region "$AWS_REGION" --name "$SECRET_NAME" \
      --description "BirdJournal: the APNs token key (issue #63)" \
      --secret-string "file://${TMPDIR:-/tmp}/birdjournal-apns.$$" >/dev/null
  fi
  rm -f "${TMPDIR:-/tmp}/birdjournal-apns.$$"
  # Cost allocation: the budget counts what is tagged project=birdjournal.
  aws secretsmanager tag-resource --region "$AWS_REGION" --secret-id "$SECRET_NAME" --tags "${TAGS[@]}"
  printf '  %s✓ stored%s %s in AWS Secrets Manager (%s)\n' "$GREEN" "$RESET" "$SECRET_NAME" "$AWS_REGION"
  if [[ "$key_path" == "$HOME/Downloads/"* ]]; then
    note "The .p8 is still in Downloads: move it to ~/keys and chmod 600, or delete it once you've backed it up."
  fi
  note "A deployed API picks the key up within five minutes, with no redeploy."
  pause
fi

if begin "Apple Developer: Push Notifications on the App ID"; then
  say "The app's Debug entitlement (aps-environment) needs the capability on its App ID for device builds."
  say "Xcode's automatic signing may have switched it on already."
  open_url "https://developer.apple.com/account/resources/identifiers/list"
  step "Open the App ID $BUNDLE_ID → Capabilities → tick 'Push Notifications' → Save → Confirm."
  note "No certificates to make: the token key replaces them. Profiles regenerate on the next build."
  pause "Press Enter once Push Notifications is on."
fi

if begin "Deploy the stack with pushes"; then
  say "infra/scripts/deploy.sh runs the template tests, checks the shared us-west-2 bootstrap (it never"
  say "bootstraps), and deploys the 15-minute digest schedule and the API's read access to $SECRET_NAME."
  if confirm "Deploy BirdJournal to $AWS_ACCOUNT / $AWS_REGION now?"; then
    "$INFRA_DIR/scripts/deploy.sh"
  else
    SKIPPED+=("deploy: infra/scripts/deploy.sh, then WIZARD_FROM=5 infra/scripts/push-wizard.sh")
    finish; exit 0
  fi
  pause
fi

if begin "Check: the stack, and a test push to your phone"; then
  secret_exists && printf '  %s✓%s %s exists\n' "$GREEN" "$RESET" "$SECRET_NAME" || warn "$SECRET_NAME is missing: WIZARD_FROM=2."
  function_name=$(api_function)
  if [[ -n "$function_name" && "$function_name" != "None" ]]; then
    configured=$(aws lambda get-function-configuration --region "$AWS_REGION" --function-name "$function_name" \
      --query 'Environment.Variables.APNS_SECRET_NAME' --output text 2>/dev/null || true)
    [[ "$configured" == "$SECRET_NAME" ]] && printf '  %s✓%s the API reads %s\n' "$GREEN" "$RESET" "$SECRET_NAME" \
      || warn "The API's function doesn't name $SECRET_NAME yet: deploy (WIZARD_FROM=4)."
  else
    warn "No BirdJournal stack found: deploy first (WIZARD_FROM=4)."
  fi
  say "On the phone: a Debug build, signed in, Circles → create or join a circle → allow notifications."
  say "Settings → Developer shows the push token and its environment."
  if confirm "Send a test push to that phone now?"; then
    until ask PUSH_TEST_TOKEN "Push token:" && [[ "$PUSH_TEST_TOKEN" =~ ^[0-9a-fA-F]{64,200}$ ]]; do warn "A token is hex."; done
    push_environment="sandbox"
    confirm "Is it a TestFlight or App Store build (production)?" && push_environment="production"
    result=$(uv run --quiet --project "$REPO_DIR/backend" python - "$PUSH_TEST_TOKEN" "$push_environment" "$SECRET_NAME" "$BUNDLE_ID" "$AWS_REGION" <<'PY'
import sys
import uuid
from datetime import datetime, timezone
from birdjournal_api.apns import ApnsSender, secrets_manager_credentials
from birdjournal_api.devices import Device, Environment
from birdjournal_api.pushes import Push, PushKind
token, environment, secret, topic, region = sys.argv[1:6]
sender = ApnsSender(secrets_manager_credentials(secret, region), topic)
# A notable push's find summary too, so a glasses run on that phone shows the lens's friend banner (#67).
find = {
    "owner": "push-wizard", "owner_name": "Maya Ortiz", "sighting_id": str(uuid.uuid4()),
    "species_id": "sayornis_nigricans", "scientific_name": "Sayornis nigricans", "common_name": "Black Phoebe",
    "method": "heard", "place": "Pasadena",
    "found_at": datetime.now(timezone.utc).replace(second=0, microsecond=0).strftime("%Y-%m-%dT%H:%M:%SZ"),
    "new_patch": True, "edition": None, "rarity": None, "circle_first": False, "circle_ids": [],
}
push = Push(kind=PushKind.NOTABLE, title="Bird Journal", body="A test push from the push wizard", data={"find": find})
print(sender.send(Device(token.lower(), Environment(environment)), push).value)
PY
) || result="error"
    case "$result" in
      sent) printf '  %s✓%s APNs took it: the phone should show "A test push from the push wizard",\n' "$GREEN" "$RESET"
            say "and a glasses run on it the friend banner \"Maya heard a Black Phoebe · Pasadena\" (#67)." ;;
      gone) warn "APNs says the token isn't valid for $BUNDLE_ID in $push_environment: check the environment." ;;
      *) warn "APNs didn't take it ($result). Check the Key ID, Team ID and the .p8, then WIZARD_FROM=2." ;;
    esac
  fi
  pause
fi

finish
note "on two devices: a new patch, or a Rare or circle-first find, on one phone pushes to the other at once; a"
note "burst of ordinary finds arrives as one digest within 15 minutes (two hours after the last push about"
note "that friend)."
printf '\n'
}

run_wizard "$@"; exit
